 const [runNumber,setRunNumber]=useState(41);
 const [runTime,setRunTime]=useState("08:00:00");
 const [hasIssue,setHasIssue]=useState(true);
 const [approval,setApproval]=useState<"pending"|"approved"|"rejected">("pending");
 const [sourceMode,setSourceMode]=useState<"synthetic"|"csv">("synthetic");
 const [csvRows,setCsvRows]=useState<FinanceRecord[]|null>(null);
 const [csvError,setCsvError]=useState("");
 const [revChange,setRevChange]=useState(-5);
 const [costChange,setCostChange]=useState(4);
 const [kpis,setKpis]=useState<Kpi[]>([]);
